CREATE TYPE public.organization_role AS ENUM ('administrator','project_manager','engineer','reviewer');
CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name))>0),created_by uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.organizations TO authenticated;
GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organization_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,role public.organization_role NOT NULL DEFAULT 'engineer',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id));
GRANT SELECT ON public.organization_members TO authenticated;
GRANT ALL ON public.organization_members TO service_role;
ALTER TABLE public.organization_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN default_organization_id uuid REFERENCES public.organizations(id);
ALTER TABLE public.profiles ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.profiles ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
INSERT INTO public.organizations(id,name,created_by) SELECT id,coalesce(nullif(trim(organisation),''),nullif(trim(full_name),''),'Private engineering workspace'),id FROM public.profiles;
INSERT INTO public.organization_members(organization_id,user_id,role) SELECT p.id,p.id,CASE WHEN EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role='admin') THEN 'administrator'::public.organization_role WHEN EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role='reviewer') THEN 'reviewer'::public.organization_role ELSE 'engineer'::public.organization_role END FROM public.profiles p;
UPDATE public.profiles SET default_organization_id=id;
CREATE FUNCTION public.organization_access(_organization_id uuid,_roles public.organization_role[] DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organization_members m JOIN public.organizations o ON o.id=m.organization_id WHERE m.organization_id=_organization_id AND m.user_id=auth.uid() AND m.status='active' AND o.status='active' AND (_roles IS NULL OR m.role=ANY(_roles))) $$;
REVOKE ALL ON FUNCTION public.organization_access(uuid,public.organization_role[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.organization_access(uuid,public.organization_role[]) TO authenticated,service_role;
CREATE POLICY organization_read ON public.organizations FOR SELECT TO authenticated USING(public.organization_access(id));
CREATE POLICY organization_update ON public.organizations FOR UPDATE TO authenticated USING(public.organization_access(id,ARRAY['administrator']::public.organization_role[])) WITH CHECK(public.organization_access(id,ARRAY['administrator']::public.organization_role[]));
CREATE POLICY membership_read ON public.organization_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.organization_access(organization_id));
CREATE TABLE public.vessels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),name text NOT NULL CHECK(length(trim(name))>0),vessel_type text NOT NULL,class_society text NOT NULL,flag text NOT NULL,length_m numeric NOT NULL CHECK(length_m>0),imo_number text CHECK(imo_number IS NULL OR imo_number ~ '^[0-9]{7}$'),status text NOT NULL DEFAULT 'design' CHECK(status IN ('design','active','retired')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,organization_id));
GRANT SELECT,INSERT,UPDATE ON public.vessels TO authenticated;
GRANT ALL ON public.vessels TO service_role;
ALTER TABLE public.vessels ENABLE ROW LEVEL SECURITY;
CREATE POLICY vessel_read ON public.vessels FOR SELECT TO authenticated USING(public.organization_access(organization_id));
CREATE POLICY vessel_insert ON public.vessels FOR INSERT TO authenticated WITH CHECK(public.organization_access(organization_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
CREATE POLICY vessel_update ON public.vessels FOR UPDATE TO authenticated USING(public.organization_access(organization_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[])) WITH CHECK(public.organization_access(organization_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
ALTER TABLE public.projects ADD COLUMN organization_id uuid REFERENCES public.organizations(id);
ALTER TABLE public.projects ADD COLUMN vessel_id uuid;
ALTER TABLE public.projects ADD COLUMN name text NOT NULL DEFAULT 'Engineering project';
ALTER TABLE public.projects ADD COLUMN status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','under_review','completed','archived'));
ALTER TABLE public.projects ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
INSERT INTO public.vessels(id,organization_id,name,vessel_type,class_society,flag,length_m) SELECT id,user_id,vessel,vessel_type,class_society,flag,length_m FROM public.projects;
UPDATE public.projects SET organization_id=user_id,vessel_id=id,name=vessel || ' design';
ALTER TABLE public.projects ALTER COLUMN organization_id SET NOT NULL;
ALTER TABLE public.projects ALTER COLUMN vessel_id SET NOT NULL;
ALTER TABLE public.projects ADD CONSTRAINT projects_vessel_organization_fk FOREIGN KEY(vessel_id,organization_id) REFERENCES public.vessels(id,organization_id);
ALTER TABLE public.projects ADD CONSTRAINT projects_id_organization_unique UNIQUE(id,organization_id);
CREATE FUNCTION public.project_access(_project_id uuid,_roles public.organization_role[] DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.projects p WHERE p.id=_project_id AND public.organization_access(p.organization_id,_roles)) $$;
REVOKE ALL ON FUNCTION public.project_access(uuid,public.organization_role[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.project_access(uuid,public.organization_role[]) TO authenticated,service_role;
ALTER POLICY project_read ON public.projects USING(public.organization_access(organization_id));
ALTER POLICY project_create ON public.projects WITH CHECK(user_id=auth.uid() AND public.organization_access(organization_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
GRANT UPDATE ON public.projects TO authenticated;
CREATE POLICY project_update ON public.projects FOR UPDATE TO authenticated USING(public.organization_access(organization_id,ARRAY['administrator','project_manager']::public.organization_role[])) WITH CHECK(public.organization_access(organization_id,ARRAY['administrator','project_manager']::public.organization_role[]));
CREATE FUNCTION public.prepare_project() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v public.vessels; BEGIN
IF TG_OP='UPDATE' AND (NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Project ownership is immutable'; END IF;
IF NEW.organization_id IS NULL THEN SELECT default_organization_id INTO NEW.organization_id FROM public.profiles WHERE id=NEW.user_id; END IF;
IF NEW.vessel_id IS NULL THEN INSERT INTO public.vessels(organization_id,name,vessel_type,class_society,flag,length_m) VALUES(NEW.organization_id,NEW.vessel,NEW.vessel_type,NEW.class_society,NEW.flag,NEW.length_m) RETURNING id INTO NEW.vessel_id; END IF;
SELECT * INTO v FROM public.vessels WHERE id=NEW.vessel_id AND organization_id=NEW.organization_id;
IF v.id IS NULL THEN RAISE EXCEPTION 'Vessel must belong to the project organization'; END IF;
NEW.vessel=v.name;NEW.vessel_type=v.vessel_type;NEW.class_society=v.class_society;NEW.flag=v.flag;NEW.length_m=v.length_m;RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.prepare_project() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER prepare_project BEFORE INSERT OR UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.prepare_project();
ALTER TABLE public.design_documents ADD COLUMN status text NOT NULL DEFAULT 'uploaded' CHECK(status IN ('uploaded','processing','ready','failed','archived'));
ALTER TABLE public.design_documents ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.design_documents ADD CONSTRAINT document_size_nonnegative CHECK(size_bytes>=0) NOT VALID;
ALTER TABLE public.design_documents ADD CONSTRAINT documents_id_project_unique UNIQUE(id,project_id);
ALTER POLICY document_read ON public.design_documents USING(public.project_access(project_id));
ALTER POLICY document_create ON public.design_documents WITH CHECK(user_id=auth.uid() AND split_part(storage_path,'/',1)=auth.uid()::text AND split_part(storage_path,'/',2)=project_id::text AND public.project_access(project_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
CREATE TABLE public.design_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),document_id uuid NOT NULL,version_number integer NOT NULL DEFAULT 1 CHECK(version_number>0),revision text NOT NULL DEFAULT 'A',storage_path text NOT NULL UNIQUE,content_sha256 text CHECK(content_sha256 IS NULL OR content_sha256 ~ '^[a-f0-9]{64}$'),status text NOT NULL DEFAULT 'uploaded' CHECK(status IN ('uploaded','extracting','ready','failed','superseded')),created_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(document_id,project_id) REFERENCES public.design_documents(id,project_id),UNIQUE(document_id,version_number),UNIQUE(id,project_id));
GRANT SELECT,INSERT ON public.design_versions TO authenticated;
GRANT ALL ON public.design_versions TO service_role;
ALTER TABLE public.design_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY version_read ON public.design_versions FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE POLICY version_insert ON public.design_versions FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.project_access(project_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]) AND split_part(storage_path,'/',1)=auth.uid()::text AND split_part(storage_path,'/',2)=project_id::text);
INSERT INTO public.design_versions(project_id,document_id,revision,storage_path,created_by) SELECT project_id,id,revision,storage_path,user_id FROM public.design_documents;
CREATE FUNCTION public.initial_design_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.design_versions(project_id,document_id,revision,storage_path,created_by) VALUES(NEW.project_id,NEW.id,NEW.revision,NEW.storage_path,NEW.user_id);RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.initial_design_version() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER initial_design_version AFTER INSERT ON public.design_documents FOR EACH ROW EXECUTE FUNCTION public.initial_design_version();
CREATE TABLE public.extracted_design_elements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,design_version_id uuid NOT NULL,element_type text NOT NULL,name text NOT NULL,value jsonb NOT NULL DEFAULT '{}'::jsonb,unit text,page_number integer CHECK(page_number>0),source_quote text,confidence numeric CHECK(confidence BETWEEN 0 AND 1),status text NOT NULL DEFAULT 'unverified' CHECK(status IN ('unverified','verified','rejected')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(design_version_id,project_id) REFERENCES public.design_versions(id,project_id),UNIQUE(id,design_version_id,project_id));
GRANT SELECT ON public.extracted_design_elements TO authenticated;
GRANT ALL ON public.extracted_design_elements TO service_role;
ALTER TABLE public.extracted_design_elements ENABLE ROW LEVEL SECURITY;
CREATE POLICY element_read ON public.extracted_design_elements FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE TABLE public.regulatory_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES public.organizations(id),publisher text NOT NULL,title text NOT NULL,rule_set_key text NOT NULL,rule_set_version text NOT NULL,source_url text NOT NULL CHECK(source_url ~ '^https://'),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','verified','retired')),verified_by uuid REFERENCES public.profiles(id),verified_at timestamptz,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,rule_set_version),CHECK(status<>'verified' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL AND published_at IS NOT NULL)));
CREATE UNIQUE INDEX source_global_version_unique ON public.regulatory_sources(rule_set_key,rule_set_version) WHERE organization_id IS NULL;
CREATE UNIQUE INDEX source_org_version_unique ON public.regulatory_sources(organization_id,rule_set_key,rule_set_version) WHERE organization_id IS NOT NULL;
GRANT SELECT ON public.regulatory_sources TO authenticated;
GRANT ALL ON public.regulatory_sources TO service_role;
ALTER TABLE public.regulatory_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY source_read ON public.regulatory_sources FOR SELECT TO authenticated USING((organization_id IS NULL AND status IN ('verified','retired')) OR public.organization_access(organization_id));
CREATE TABLE public.regulatory_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),regulatory_source_id uuid NOT NULL,rule_set_version text NOT NULL,clause_reference text NOT NULL,requirement_text text NOT NULL,category text NOT NULL,applicability jsonb NOT NULL DEFAULT '{}'::jsonb,deterministic_rule jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','retired')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(regulatory_source_id,rule_set_version) REFERENCES public.regulatory_sources(id,rule_set_version),UNIQUE(regulatory_source_id,clause_reference),UNIQUE(id,regulatory_source_id,rule_set_version));
GRANT SELECT ON public.regulatory_requirements TO authenticated;
GRANT ALL ON public.regulatory_requirements TO service_role;
ALTER TABLE public.regulatory_requirements ENABLE ROW LEVEL SECURITY;
CREATE POLICY requirement_read ON public.regulatory_requirements FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.regulatory_sources s WHERE s.id=regulatory_source_id));
CREATE TABLE public.compliance_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),design_version_id uuid NOT NULL,regulatory_source_id uuid NOT NULL,rule_set_version text NOT NULL,requested_by uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','requires_review','completed','failed','cancelled')),overall_status text NOT NULL DEFAULT 'REQUIRES_REVIEW' CHECK(overall_status IN ('REQUIRES_REVIEW','NON_COMPLIANT','COMPLIANT')),engine_version text,started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(design_version_id,project_id) REFERENCES public.design_versions(id,project_id),FOREIGN KEY(regulatory_source_id,rule_set_version) REFERENCES public.regulatory_sources(id,rule_set_version),UNIQUE(id,project_id),UNIQUE(id,project_id,regulatory_source_id,rule_set_version),UNIQUE(id,project_id,design_version_id));
GRANT SELECT,INSERT ON public.compliance_assessments TO authenticated;
GRANT ALL ON public.compliance_assessments TO service_role;
ALTER TABLE public.compliance_assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assessment_read ON public.compliance_assessments FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE POLICY assessment_request ON public.compliance_assessments FOR INSERT TO authenticated WITH CHECK(requested_by=auth.uid() AND status='queued' AND overall_status='REQUIRES_REVIEW' AND public.project_access(project_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
CREATE TABLE public.compliance_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assessment_id uuid NOT NULL,project_id uuid NOT NULL,regulatory_requirement_id uuid NOT NULL,regulatory_source_id uuid NOT NULL,rule_set_version text NOT NULL,title text NOT NULL,deterministic_status text NOT NULL DEFAULT 'REQUIRES_REVIEW' CHECK(deterministic_status IN ('REQUIRES_REVIEW','NON_COMPLIANT','COMPLIANT')),severity text NOT NULL DEFAULT 'medium' CHECK(severity IN ('low','medium','high','critical')),review_status text NOT NULL DEFAULT 'open' CHECK(review_status IN ('open','accepted','overridden')),interpretation text,recommendation text,engine_version text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(assessment_id,project_id,regulatory_source_id,rule_set_version) REFERENCES public.compliance_assessments(id,project_id,regulatory_source_id,rule_set_version),FOREIGN KEY(regulatory_requirement_id,regulatory_source_id,rule_set_version) REFERENCES public.regulatory_requirements(id,regulatory_source_id,rule_set_version),UNIQUE(id,assessment_id,project_id));
GRANT SELECT ON public.compliance_findings TO authenticated;
GRANT ALL ON public.compliance_findings TO service_role;
ALTER TABLE public.compliance_findings ENABLE ROW LEVEL SECURITY;
CREATE POLICY finding_read ON public.compliance_findings FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE TABLE public.engineering_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,assessment_id uuid NOT NULL,finding_id uuid NOT NULL,reviewer_id uuid NOT NULL REFERENCES public.profiles(id),decision text NOT NULL CHECK(decision IN ('accept','override','request_changes')),rationale text NOT NULL CHECK(length(trim(rationale))>0),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(finding_id,assessment_id,project_id) REFERENCES public.compliance_findings(id,assessment_id,project_id));
GRANT SELECT,INSERT ON public.engineering_reviews TO authenticated;
GRANT ALL ON public.engineering_reviews TO service_role;
ALTER TABLE public.engineering_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY review_read ON public.engineering_reviews FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE POLICY review_insert ON public.engineering_reviews FOR INSERT TO authenticated WITH CHECK(reviewer_id=auth.uid() AND public.project_access(project_id,ARRAY['administrator','reviewer']::public.organization_role[]));
CREATE TABLE public.assessment_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,assessment_id uuid NOT NULL,design_version_id uuid NOT NULL,finding_id uuid NOT NULL,extracted_element_id uuid,page_number integer CHECK(page_number>0),source_quote text NOT NULL CHECK(length(trim(source_quote))>0),verified boolean NOT NULL DEFAULT false,verified_by uuid REFERENCES public.profiles(id),verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(assessment_id,project_id,design_version_id) REFERENCES public.compliance_assessments(id,project_id,design_version_id),FOREIGN KEY(finding_id,assessment_id,project_id) REFERENCES public.compliance_findings(id,assessment_id,project_id),FOREIGN KEY(extracted_element_id,design_version_id,project_id) REFERENCES public.extracted_design_elements(id,design_version_id,project_id),CHECK(NOT verified OR (verified_by IS NOT NULL AND verified_at IS NOT NULL)));
GRANT SELECT ON public.assessment_evidence TO authenticated;
GRANT ALL ON public.assessment_evidence TO service_role;
ALTER TABLE public.assessment_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_read ON public.assessment_evidence FOR SELECT TO authenticated USING(public.project_access(project_id));
CREATE TABLE public.activity_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),project_id uuid,actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,organization_id) REFERENCES public.projects(id,organization_id));
GRANT SELECT ON public.activity_logs TO authenticated;
GRANT ALL ON public.activity_logs TO service_role;
ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activity_logs FOR SELECT TO authenticated USING(public.organization_access(organization_id));
CREATE FUNCTION public.profile_organization_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NEW.default_organization_id IS NOT NULL AND NOT public.organization_access(NEW.default_organization_id) THEN RAISE EXCEPTION 'Default organization requires active membership';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.profile_organization_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profile_organization_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profile_organization_guard();
CREATE OR REPLACE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org_id uuid; BEGIN
INSERT INTO public.profiles(id,full_name,organisation) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',''),coalesce(NEW.raw_user_meta_data->>'organisation',''));
INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'engineer');
INSERT INTO public.organizations(name,created_by) VALUES(coalesce(nullif(trim(NEW.raw_user_meta_data->>'organisation'),''),'Private engineering workspace'),NEW.id) RETURNING id INTO org_id;
INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(org_id,NEW.id,'engineer');
UPDATE public.profiles SET default_organization_id=org_id WHERE id=NEW.id;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.storage_project_access(_name text,_roles public.organization_role[] DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.projects p WHERE p.id::text=split_part(_name,'/',2) AND public.organization_access(p.organization_id,_roles)) $$;
REVOKE ALL ON FUNCTION public.storage_project_access(text,public.organization_role[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.storage_project_access(text,public.organization_role[]) TO authenticated,service_role;
ALTER POLICY design_file_read ON storage.objects USING(bucket_id='design-documents' AND public.storage_project_access(name) AND (EXISTS(SELECT 1 FROM public.design_versions v WHERE v.storage_path=name) OR EXISTS(SELECT 1 FROM public.design_documents d WHERE d.storage_path=name)));
ALTER POLICY design_file_upload ON storage.objects WITH CHECK(bucket_id='design-documents' AND split_part(name,'/',1)=auth.uid()::text AND public.storage_project_access(name,ARRAY['administrator','project_manager','engineer']::public.organization_role[]));
ALTER POLICY design_file_cleanup ON storage.objects USING(bucket_id='design-documents' AND split_part(name,'/',1)=auth.uid()::text AND public.storage_project_access(name,ARRAY['administrator','project_manager','engineer']::public.organization_role[]) AND NOT EXISTS(SELECT 1 FROM public.design_documents d WHERE d.storage_path=name) AND NOT EXISTS(SELECT 1 FROM public.design_versions v WHERE v.storage_path=name));
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now();RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.touch_updated_at() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.audit_project_entity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE row_data jsonb;pid uuid;org_id uuid;BEGIN row_data=to_jsonb(NEW);IF TG_TABLE_NAME='projects' THEN pid=NEW.id;org_id=NEW.organization_id;ELSE pid=(row_data->>'project_id')::uuid;SELECT organization_id INTO org_id FROM public.projects WHERE id=pid;END IF;INSERT INTO public.activity_logs(organization_id,project_id,actor_id,action,entity_type,entity_id) VALUES(org_id,pid,auth.uid(),lower(TG_OP),TG_TABLE_NAME,NEW.id);RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.audit_project_entity() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.validate_assessment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE source public.regulatory_sources;org_id uuid;BEGIN
SELECT * INTO source FROM public.regulatory_sources WHERE id=NEW.regulatory_source_id;SELECT organization_id INTO org_id FROM public.projects WHERE id=NEW.project_id;
IF source.status<>'verified' OR source.verified_at IS NULL OR source.published_at IS NULL OR (source.organization_id IS NOT NULL AND source.organization_id IS DISTINCT FROM org_id) THEN RAISE EXCEPTION 'Assessment requires a verified rule-set authorized for this organization';END IF;
IF TG_OP='UPDATE' AND (NEW.project_id,NEW.design_version_id,NEW.regulatory_source_id,NEW.rule_set_version) IS DISTINCT FROM (OLD.project_id,OLD.design_version_id,OLD.regulatory_source_id,OLD.rule_set_version) THEN RAISE EXCEPTION 'Assessment version references are immutable';END IF;
IF NEW.overall_status='COMPLIANT' AND (NEW.status<>'completed' OR NOT EXISTS(SELECT 1 FROM public.compliance_findings WHERE assessment_id=NEW.id) OR EXISTS(SELECT 1 FROM public.compliance_findings f WHERE f.assessment_id=NEW.id AND (f.deterministic_status<>'COMPLIANT' OR f.review_status='open' OR NOT EXISTS(SELECT 1 FROM public.assessment_evidence e WHERE e.finding_id=f.id AND e.verified)))) THEN RAISE EXCEPTION 'Open findings or missing verified evidence prevent compliance';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.validate_assessment() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_assessment BEFORE INSERT OR UPDATE ON public.compliance_assessments FOR EACH ROW EXECUTE FUNCTION public.validate_assessment();
CREATE FUNCTION public.protect_version_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_TABLE_NAME='design_versions' THEN IF EXISTS(SELECT 1 FROM public.compliance_assessments WHERE design_version_id=OLD.id) THEN RAISE EXCEPTION 'Assessed design versions are immutable';END IF;
ELSIF TG_TABLE_NAME='regulatory_sources' THEN IF OLD.status='verified' OR EXISTS(SELECT 1 FROM public.compliance_assessments WHERE regulatory_source_id=OLD.id) THEN RAISE EXCEPTION 'Published rule-set versions are immutable';END IF;
ELSIF TG_TABLE_NAME='regulatory_requirements' THEN IF EXISTS(SELECT 1 FROM public.regulatory_sources WHERE id=OLD.regulatory_source_id AND status IN ('verified','retired')) THEN RAISE EXCEPTION 'Published requirements are immutable';END IF;END IF;
IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.protect_version_record() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER protect_design_version BEFORE UPDATE OR DELETE ON public.design_versions FOR EACH ROW EXECUTE FUNCTION public.protect_version_record();
CREATE TRIGGER protect_rule_set BEFORE UPDATE OR DELETE ON public.regulatory_sources FOR EACH ROW EXECUTE FUNCTION public.protect_version_record();
CREATE TRIGGER protect_requirement BEFORE UPDATE OR DELETE ON public.regulatory_requirements FOR EACH ROW EXECUTE FUNCTION public.protect_version_record();
COMMENT ON TABLE public.user_roles IS 'Legacy account role compatibility only; organization_members is authoritative for all workspace authorization.';
COMMENT ON COLUMN public.projects.vessel IS 'Compatibility mirror; vessels is the canonical vessel record.';
COMMENT ON COLUMN public.projects.vessel_type IS 'Compatibility mirror; vessels is the canonical vessel record.';
COMMENT ON COLUMN public.projects.class_society IS 'Compatibility mirror; vessels is the canonical vessel record.';
COMMENT ON COLUMN public.projects.flag IS 'Compatibility mirror; vessels is the canonical vessel record.';
COMMENT ON COLUMN public.projects.length_m IS 'Compatibility mirror; vessels is the canonical vessel record.';
COMMENT ON COLUMN public.projects.version IS 'Legacy display label; assessments use design_versions IDs.';
COMMENT ON COLUMN public.profiles.organisation IS 'Editable display label only; never used to grant organization membership.';
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['profiles','organizations','organization_members','vessels','projects','design_documents','design_versions','extracted_design_elements','regulatory_sources','regulatory_requirements','compliance_assessments','compliance_findings'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t || '_updated_at',t);END LOOP;
FOREACH t IN ARRAY ARRAY['projects','design_documents','design_versions','extracted_design_elements','compliance_assessments','compliance_findings','engineering_reviews','assessment_evidence'] LOOP EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_project_entity()',t || '_audit',t);END LOOP;END $$;
CREATE INDEX organization_members_access_idx ON public.organization_members(user_id,organization_id);
CREATE INDEX projects_organization_idx ON public.projects(organization_id);
CREATE INDEX vessels_organization_idx ON public.vessels(organization_id);
CREATE INDEX versions_project_idx ON public.design_versions(project_id);
CREATE INDEX elements_version_idx ON public.extracted_design_elements(design_version_id,project_id);
CREATE INDEX requirements_source_idx ON public.regulatory_requirements(regulatory_source_id);
CREATE INDEX assessments_project_idx ON public.compliance_assessments(project_id,design_version_id);
CREATE INDEX findings_assessment_idx ON public.compliance_findings(assessment_id);
CREATE INDEX reviews_finding_idx ON public.engineering_reviews(finding_id);
CREATE INDEX evidence_finding_idx ON public.assessment_evidence(finding_id,assessment_id);
CREATE INDEX activity_organization_idx ON public.activity_logs(organization_id,created_at);